fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Ensure both arrays have the same length
    assert_eq!(
        arr1.len(),
        arr2.len(),
        "Input arrays must have the same length"
    );

    // Allocate a result vector with the same length
    let mut result = Vec::with_capacity(arr1.len());

    // Compute the bitwise XOR for each pair of elements
    for (a, b) in arr1.iter().zip(arr2.iter()) {
        result.push(a ^ b);
    }

    result
}

